<?php require '../config/db.php';require '../includes/functions.php';require '../includes/mailer.php';$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$service=trim($_POST['service']??'');$message=trim($_POST['message']??'');if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($phone)<5||$service===''||strlen($message)<5)json_response(false,'Please correct the highlighted information and try again.',[],422);$pdo->prepare('INSERT INTO contacts(name,email,phone,service,message,status) VALUES(?,?,?,?,?,\'new\')')->execute([$name,$email,$phone,$service,$message]);$admin=envv('MAIL_ADMIN_ADDRESS');$safe=e($message);$visitor=send_mail_message($email,'We received your enquiry',"<h2>Thank you, ".e($name).".</h2><p>We received your message about <b>".e($service)."</b> and will respond as soon as possible.</p>");$adm=$admin?send_mail_message($admin,'New website enquiry',"<h2>New enquiry</h2><p><b>Name:</b> ".e($name)."</p><p><b>Email:</b> ".e($email)."</p><p><b>Phone:</b> ".e($phone)."</p><p><b>Service:</b> ".e($service)."</p><p>".$safe."</p>"):false;json_response(true,($visitor&&$adm)?'Message sent and confirmation emails delivered.':'Message saved successfully. Email delivery needs valid server mail settings in .env.');